-- ---------- Staff, linked to Supabase Auth users by email ----------
-- A user that doesn't exist in auth.users yet is skipped: the select returns no rows.
-- Teams and roles are replaced, so the database always matches airport.json.

-- cleaning@demo.flare.invalid
insert into flare.staff_member (id, display_name, active)
    select id, 'Ana (simulat)', true from auth.users where email = 'cleaning@demo.flare.invalid'
    on conflict (id) do update set display_name = excluded.display_name, active = true;
delete from flare.staff_member_team where staff_member_id in (select id from auth.users where email = 'cleaning@demo.flare.invalid');
delete from flare.staff_member_role where staff_member_id in (select id from auth.users where email = 'cleaning@demo.flare.invalid');
insert into flare.staff_member_team (staff_member_id, team_id) select id, 'CLEANING' from flare.staff_member where id in (select id from auth.users where email = 'cleaning@demo.flare.invalid');
insert into flare.staff_member_role (staff_member_id, role_id) select id, 'STAFF' from flare.staff_member where id in (select id from auth.users where email = 'cleaning@demo.flare.invalid');

